steps.code:
[[extensions]]
name = "Regras de pagamento"
handle = "regras-pagamento"
type = "function"

  [[extensions.targeting]]
  target = "cart.payment-methods.transform.run"
  input_query = "src/cart_payment_methods_transform_run.graphql"
  export = "cart-payment-methods-transform-run"

query CartPaymentMethodsTransformRunInput {
  cart {
    cost {
      totalAmount {
        amount
      }
    }
    buyerIdentity {
      purchasingCompany {
        company {
          name
        }
      }
    }
  }
  paymentMethods {
    id
    name
  }
}

// src/cart_payment_methods_transform_run.js
export function cartPaymentMethodsTransformRun(input) {
  const operations = [];
  const total = Number(input.cart.cost.totalAmount.amount);
  const isB2B = Boolean(input.cart.buyerIdentity?.purchasingCompany);

  for (const method of input.paymentMethods) {
    const name = method.name.toLowerCase();

    // 1) boleto só a partir de R$ 50
    if (name.includes("boleto") && total < 50) {
      operations.push({ paymentMethodHide: { paymentMethodId: method.id } });
    }

    // 2) B2B: cartão de crédito vai pro fim da lista
    if (isB2B && name.includes("cartão")) {
      operations.push({ paymentMethodMove: { paymentMethodId: method.id, index: 99 } });
    }

    // 3) renomeia o Pix
    if (name.includes("pix")) {
      operations.push({
        paymentMethodRename: { paymentMethodId: method.id, name: "Pix (aprovação imediata)" },
      });
    }
  }

  return { operations };
}

// Só Shopify Plus + B2B: exige revisão manual do lojista antes de concluir o pedido
operations.push({
  orderReviewAdd: { reason: "Primeiro pedido acima de R$ 20.000 — conferir crédito" },
});
